import React, { forwardRef } from 'react';
import styled from 'styled-components';

import Animations from '@dynatrace/strato-design-tokens/animations';
import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';

import { PANEL_ORDER, MIN_WIDTHS } from './Page.js';
import { _usePanelsContext } from './Panel/hooks/_usePanelsContext.js';
import { Panel } from './Panel/Panel.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';

// #region Styled components
const StyledMain = /* @__PURE__ */ styled(Panel)<{
  $leftBorderRadius: boolean;
  $rightBorderRadius: boolean;
}>(({ $leftBorderRadius, $rightBorderRadius }) => ({
  backgroundColor: Colors.Background.Base.Default,
  borderRadius: `${$leftBorderRadius ? Borders.Radius.Surface.Default : 0} ${
    $rightBorderRadius ? Borders.Radius.Surface.Default : 0
  } 0 0`,
  transition: `border-radius ${Animations.FadeIn.Duration.Fast} ${Animations.FadeIn.Easing}`,

  '@media(prefers-reduced-motion)': {
    transition: '',
  },
}));
StyledMain.displayName = 'Page.Main';
// #endregion

export interface MainProps
  extends WithChildren,
    Omit<React.HTMLAttributes<HTMLDivElement>, 'onResize' | keyof StylingProps>,
    StylingProps,
    DataTestId {
  /**
   * The minimum width of the main panel in pixels.
   * @defaultValue 320
   */
  minWidth?: number;
}

/**
 * The `Main` component is used inside the `Page` component for displaying content in the corresponding panel.
 * It is the only compound that is mandatory for rendering the `Page`.
 */
export const Main = forwardRef<HTMLDivElement, MainProps>(
  (props, forwardedRef) => {
    const {
      children,
      minWidth = MIN_WIDTHS.main,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: MainProps = props;

    const {
      state: { panels },
    } = _usePanelsContext();

    const hasSidebar = !!panels['sidebar'];
    const hasDetailView = !!panels['details'];

    return (
      <StyledMain
        {...remainingProps}
        data-testid={dataTestId}
        ref={forwardedRef}
        name="main"
        order={PANEL_ORDER.main}
        minWidth={minWidth}
        dismissible={false}
        className={consumerClassName}
        style={consumerStyle}
        $leftBorderRadius={hasSidebar}
        $rightBorderRadius={hasDetailView}
      >
        {children}
      </StyledMain>
    );
  },
);

(Main as typeof Main & { displayName: string }).displayName = 'Page.Main';
